104	  return (
105	    <section className={'results-panel' + (c.plan ? ' revealed' : '')}>
106	      <div className="panel-heading">
107	        <div>
108	          <h2>See the impact</h2>
109	          <p id="result-label">{c.plan ? 'Baseline versus your applied scenario.' : 'Your baseline, before a shock.'}</p>
110	        </div>
111	      </div>
112	      <div id="results">
113	        {c.plan ? <PlanResults c={c} /> : (
114	          <>
115	            <div className="empty">
116	              <div className="empty-icon">↗</div>
117	              <h3>One change can tell a bigger story.</h3>
118	              <p>Describe a scenario to compare your starting point<br />with what happens next.</p>
119	            </div>
120	            <details className="data">
121	              <summary>Explore the full account baseline</summary>
122	              <pre>{JSON.stringify(c.baseline, null, 2)}</pre>
123	            </details>
124	          </>
125	        )}
126	      </div>
127	    </section>
128	  );
129	}
